const body = $input.first().json.body ?? $input.first().json;

const telefono = String(body.telefono || body.from || '').replace(/\D/g, '');
const accion = String(body.accion || 'cotizar').toLowerCase();

if (!telefono) throw new Error('Falta telefono');
if (!body.fecha_renta) throw new Error('Falta fecha_renta (YYYY-MM-DD)');
if (!body.hora_inicio) throw new Error('Falta hora_inicio (HH:MM)');
if (!body.hora_fin) throw new Error('Falta hora_fin (HH:MM)');
if (!Array.isArray(body.productos) || body.productos.length === 0) {
  throw new Error('Falta arreglo productos con al menos un item {id, cantidad}');
}

return [{
  json: {
    accion,
    telefono,
    cliente_nombre: body.nombre || body.cliente_nombre || '',
    cliente_direccion: body.direccion || body.calle_y_numero || '',
    cliente_colonia: body.colonia || '',
    cliente_ciudad: body.ciudad || body.ciudad_o_municipio || '',
    fecha_renta: body.fecha_renta,
    hora_inicio: body.hora_inicio,
    hora_fin: body.hora_fin,
    productos: body.productos,
    manteles_regalo: body.manteles_regalo || null,
    anticipo: body.anticipo || 0,
    notas: body.notas || body.comentarios || '',
    mismo_domicilio: body.mismo_domicilio ?? true,
    crm_base: 'https://app.trotacrm.com/v1'
  }
}];

const pedido = $('Normalizar Datos').first().json;
const promo = $input.first().json;

let manteles = pedido.manteles_regalo;

if (!manteles || !manteles.length) {
  manteles = [];
  const opciones = promo.opciones || {};

  for (const [familia, data] of Object.entries(opciones)) {
    const cantidad = data.cantidad_regalo || 0;
    const colores = (data.colores_disponibles || [])
      .filter((c) => (c.unidades_libres ?? 0) > 0)
      .sort((a, b) => (b.unidades_libres || 0) - (a.unidades_libres || 0));

    let restante = cantidad;
    for (const color of colores) {
      if (restante <= 0) break;
      const tomar = Math.min(restante, color.unidades_libres || 0);
      if (tomar <= 0) continue;
      manteles.push({ producto_id: color.id, cantidad: tomar });
      restante -= tomar;
    }

    if (restante > 0) {
      throw new Error(`No hay stock suficiente de manteles ${familia} para el regalo (${restante} faltante).`);
    }
  }
}

return [{
  json: {
    ...pedido,
    manteles_regalo: manteles,
    promo
  }
}];

const pedido = $('Elegir Manteles Regalo').first().json;
const cotizacion = $('Cotizar Plan').first().json;
const renta = $input.first().json;

const lineas = (cotizacion.lineas || []).map((l) => {
  const regalo = l.es_regalo ? ' (REGALO)' : '';
  return `- ${l.cantidad}x ${l.nombre}${regalo}: $${l.subtotal}`;
}).join('\n');

const mensaje = [
  '✅ *Plan confirmado en TROTA CRM*',
  '',
  `Folio: *${renta.folio}*`,
  `Cliente: ${renta.cliente?.nombre || pedido.cliente_nombre}`,
  `Fecha: ${pedido.fecha_renta} ${pedido.hora_inicio}-${pedido.hora_fin}`,
  '',
  '*Detalle:*',
  lineas,
  '',
  `Total: *$${renta.total}*`,
  `Anticipo: $${renta.anticipo}`,
  `Saldo: *$${renta.saldo_pendiente}*`,
].join('\n');

return [{
  json: {
    ok: true,
    tipo: 'renta_creada',
    mensaje_whatsapp: mensaje,
    folio: renta.folio,
    renta_id: renta.renta_id,
    total: renta.total,
    saldo_pendiente: renta.saldo_pendiente,
    cotizacion,
    renta
  }
}];

const pedido = $('Elegir Manteles Regalo').first().json;
const cotizacion = $('Cotizar Plan').first().json;

const lineas = (cotizacion.lineas || []).map((l) => {
  const regalo = l.es_regalo ? ' (REGALO)' : '';
  return `- ${l.cantidad}x ${l.nombre}${regalo}: $${l.subtotal}`;
}).join('\n');

let titulo = '📋 *Cotización TROTA*';
let extra = '';

if (!cotizacion.disponible) {
  titulo = '⚠️ *Cotización con faltantes de stock*';
  extra = (cotizacion.productos_no_disponibles || [])
    .map((p) => `- ${p.nombre}: solo ${p.unidades_libres} libre(s)`)
    .join('\n');
}

if (pedido.accion === 'crear' && !cotizacion.disponible) {
  extra += '\n\nNo se creó la renta porque falta inventario.';
}

const promo = cotizacion.promo_mantel || {};
const regalos = promo.total_regalos || 0;

const mensaje = [
  titulo,
  '',
  `Fecha evento: ${pedido.fecha_renta} ${pedido.hora_inicio}-${pedido.hora_fin}`,
  regalos > 0 ? `Manteles regalo incluidos: ${regalos}` : 'Sin promo de mantel',
  '',
  '*Detalle:*',
  lineas,
  '',
  `Total: *$${cotizacion.total}*`,
  extra ? ['', extra].join('\n') : '',
  pedido.accion === 'cotizar' ? '\nResponde *CONFIRMAR* para crear el pedido.' : ''
].filter(Boolean).join('\n');

return [{
  json: {
    ok: cotizacion.disponible,
    tipo: pedido.accion === 'crear' ? 'renta_no_creada' : 'cotizacion',
    mensaje_whatsapp: mensaje,
    disponible: cotizacion.disponible,
    total: cotizacion.total,
    cotizacion
  }
}];
